-- 1128: Blog post — "DP-700 Fabric Data Engineer in Singapore: Exam Domains, Funding and Practice Exams"
--
--       Lead-in post for WSQ - Microsoft Certified Fabric Data Engineer Associate (DP-700) Training (TGS-2024042602).
--       Backdated to 2025-10-03 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $2,000.00, GST $180.00 (9%), baseline nett $1,180.00
--     (SG/PR 21+, 50%), MCES/SME nett $780.00 (SG 40+, 70%).
--   * Course information: 4 days / 32 hrs, Intermediate, 2 hrs assessment.
--   * Funding validity 4 Mar 2024 - 3 Mar 2028; Absentee Payroll $4.50/hr.
--   * Skills Framework: Data Engineering (ICT-DIT-3005-1.1).
--   * Exam weightings from the official study guide, skills measured as of 21 Jul 2026.
--   * No exam-specific practice-exam URL exists, so the post links only the portal root
--     (never a deep link that 404s).
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'DP-700 Fabric Data Engineer in Singapore: Exam Domains, Funding and Practice Exams', 'dp-700-fabric-data-engineer-singapore-guide', 'DP-700 is the Microsoft credential for data engineers building lakehouses and real-time pipelines on Microsoft Fabric. This guide walks the exam domains and their weightings, sets out exactly what you pay after WSQ funding &mdash; $1,180 nett, or $780 for Singapore Citizens aged 40 and above &mdash; and shows what the 4 days course covers.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>DP-700</strong> is the Microsoft credential for data engineers building lakehouses and real-time pipelines on Microsoft Fabric. This guide covers what the exam measures, what the 4 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$1,180</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$780</strong> for Singapore Citizens aged 40 and above.</p></div><h2>Why DP-700 is worth sitting</h2><p>Microsoft Fabric consolidated what used to be half a dozen separate services into one analytics platform, and organisations that standardised on Power BI are now being pulled towards it. DP-700 certifies you can build on it &mdash; ingestion, lakehouses, real-time intelligence, warehousing and the operational side of keeping it running.</p><ul><li><strong>The exam is split evenly three ways</strong> &mdash; managing the analytics solution, ingesting and transforming data, and monitoring and optimising &mdash; so no area can be skipped.</li><li><strong>Fabric is Microsoft&rsquo;s strategic analytics platform</strong>, and early certified practitioners are scarce in the Singapore market.</li><li><strong>Real-time intelligence and eventstreams are covered hands-on</strong>, not just warehousing.</li><li><strong>CI/CD and security for Fabric are included</strong>, which is what separates a prototype from a production deployment.</li></ul><p>The course is mapped to the Skills Framework under <strong>Data Engineering</strong> (TSC code ICT-DIT-3005-1.1), and leads to roles such as Data Engineer, Business Intelligence Analyst, Data Warehouse Developer, Data Integration Specialist. <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-fabric-data-engineer-associate-dp-700-training.html">Check the funding you qualify for</a>.</p><h2>The DP-700 exam at a glance</h2><table><tbody><tr><td>Exam</td><td>DP-700: Implementing Data Engineering Solutions Using Microsoft Fabric</td></tr><tr><td>Length</td><td>100 minutes</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled &mdash; not 70%)</td></tr><tr><td>Certification</td><td>Fabric Data Engineer Associate</td></tr><tr><td>Renewal</td><td>Free online renewal every 12 months</td></tr></tbody></table><h2>DP-700 exam domains and weightings</h2><p>DP-700 is an unusually even exam &mdash; all three skill areas carry roughly the same weight, so no single domain can be skipped.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Implement and manage an analytics solution</td><td>30&ndash;35%</td></tr><tr><td>Ingest and transform data</td><td>30&ndash;35%</td></tr><tr><td>Monitor and optimize an analytics solution</td><td>30&ndash;35%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of 21 Jul 2026.</em></p><h2>What the WSQ course covers</h2><p>The 4 days (32 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-fabric-data-engineer-associate-dp-700-training.html"><strong>WSQ - Microsoft Certified Fabric Data Engineer Associate (DP-700) Training</strong></a> course is pitched at <strong>Intermediate</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>Ingest data with Microsoft Fabric</li><li>Implement a Lakehouse with Microsoft Fabric</li><li>Implement Real-Time Intelligence with Microsoft Fabric</li><li>Implement a data warehouse with Microsoft Fabric</li><li>Manage a Microsoft Fabric environment</li></ol><h2>Practise before you book the exam</h2><p>Course participants get access to our <a href="https://exams.tertiaryinfotech.com/practice-exams">Practice Exam Portal</a>, which carries timed mock papers across the Microsoft certification track. Rehearsing under exam conditions is the single best predictor of a first-time pass.</p><h2>What you actually pay: funding for DP-700 training</h2><p>The full fee is $2,000 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$2,180</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$1,180</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$780</strong></td></tr></tbody></table><p><em>GST of $180 is charged at 9% on the full course fee of $2,000, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><p>Funding for this course is valid from <strong>4 Mar 2024</strong> to <strong>3 Mar 2028</strong>. You must register and complete the course within that window to qualify.</p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-fabric-data-engineer-associate-dp-700-training.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>Your route to certification</h2><ol><li><strong>Register for the 4 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-fabric-data-engineer-associate-dp-700-training.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li><li><strong>Book and sit DP-700</strong> through Pearson VUE. The certification exam is booked and paid for separately from the course.</li></ol><h2>Where to go after DP-700</h2><p><a href="https://www.tertiarycourses.com.sg/dp-600-microsoft-certified-fabric-analytics-engineer-associate.html">DP-600, the Fabric Analytics Engineer Associate</a>, is the companion credential on the analytics side. For reporting specifically, <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-power-bi-data-analyst-associate-pl-300.html">PL-300</a> covers Power BI in depth. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need Power BI or Azure experience first?</summary><div class="mmd-faq-a"><p>This is an intermediate-level course. Familiarity with data concepts and SQL is assumed; DP-900 is a useful starting point if you are new to the Azure data platform.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Does the course cover Spark and notebooks?</summary><div class="mmd-faq-a"><p>Yes. Apache Spark in Fabric, Delta Lake tables and notebook-based transformation are all part of the ingestion and lakehouse modules.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the exam fee included?</summary><div class="mmd-faq-a"><p>No. The course fee covers training and the WSQ assessment. The DP-700 exam is booked separately through Pearson VUE.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">How is DP-700 different from DP-600?</summary><div class="mmd-faq-a"><p>DP-700 is the data-engineering credential &mdash; pipelines, lakehouses and real-time ingestion. DP-600 is the analytics-engineering credential, focused on semantic models and analytical workloads.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">What funding is available?</summary><div class="mmd-faq-a"><p>Singapore Citizens and PRs aged 21 and above get 50% subsidy, rising to 70% for Citizens aged 40 and above, plus SkillsFuture Credit, PSEA and UTAP.</p></div></details></div><h2>Register for Fabric Data Engineer training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-fabric-data-engineer-associate-dp-700-training.html"><strong>WSQ - Microsoft Certified Fabric Data Engineer Associate (DP-700) Training</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-10-03', 'TGS-2024042602', 'TGS-2024042602', 'DP-700 Course Singapore | Fabric Data Engineer | WSQ Funding', 'Train for DP-700 Fabric Data Engineer in Singapore. 4 days WSQ course from $780 nett after funding, full exam domain breakdown.', 'dp-700 course singapore, fabric data engineer certification, dp-700 exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, dp-700 funding, dp-700 training singapore', 'manual-skip-no-share', '2025-10-03 09:00:00', '2025-10-03 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'dp-700-fabric-data-engineer-singapore-guide');

