INSERT INTO `tag` (`name`, `status`) SELECT 'DP-700', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'DP-700') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Data Engineering', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Data Engineering') x);
